import React, { useState, useRef, useEffect, useCallback } from 'react';
import './ColorMatchingGame.css';

const ColorMatchingGame = () => {
  // State for the game
  const [targetColor, setTargetColor] = useState({ h: 0, s: 0, l: 50 }); // HSL format
  const [selectedColor, setSelectedColor] = useState({ h: 0, s: 0, l: 50 });
  const [hoverColor, setHoverColor] = useState(null); // For hover preview
  const [score, setScore] = useState(null);
  const [gameStarted, setGameStarted] = useState(false);
  const [showResult, setShowResult] = useState(false);
  const [colorSelected, setColorSelected] = useState(false);

  // Refs for the color wheel canvas
  const wheelCanvasRef = useRef(null);

  // Generate a random target color when starting a new game
  const generateNewTarget = useCallback(() => {
    const randomHue = Math.floor(Math.random() * 360); // 0-359 degrees
    const randomSaturation = Math.floor(Math.random() * 80) + 20; // 20-100% (avoid too pale colors)
    const randomLightness = Math.floor(Math.random() * 40) + 30; // 30-70% (avoid too dark/light)

    const newTarget = { h: randomHue, s: randomSaturation, l: randomLightness };
    setTargetColor(newTarget);
    setSelectedColor({ h: 0, s: 0, l: 50 }); // Reset selection to neutral
    setHoverColor(null);
    setScore(null);
    setShowResult(false);
    setColorSelected(false);
    setGameStarted(true);
  }, []);

  // Convert HSL to RGB for display
  const hslToRgb = (h, s, l) => {
    s /= 100;
    l /= 100;
    const c = (1 - Math.abs(2 * l - 1)) * s;
    const x = c * (1 - Math.abs((h / 60) % 2 - 1));
    const m = l - c / 2;
    let r, g, b;

    if (0 <= h && h < 60) {
      r = c; g = x; b = 0;
    } else if (60 <= h && h < 120) {
      r = x; g = c; b = 0;
    } else if (120 <= h && h < 180) {
      r = 0; g = c; b = x;
    } else if (180 <= h && h < 240) {
      r = 0; g = x; b = c;
    } else if (240 <= h && h < 300) {
      r = x; g = 0; b = c;
    } else if (300 <= h && h < 360) {
      r = c; g = 0; b = x;
    }

    r = Math.round((r + m) * 255);
    g = Math.round((g + m) * 255);
    b = Math.round((b + m) * 255);

    return { r, g, b };
  };

  // Convert HSL to CSS color string
  const hslToCss = (hsl) => {
    return `hsl(${hsl.h}, ${hsl.s}%, ${hsl.l}%)`;
  };

  // Draw the color wheel on canvas
  const drawColorWheel = useCallback(() => {
    const canvas = wheelCanvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = Math.min(centerX, centerY) - 10; // Leave some padding

    // Clear the canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw the color wheel
    for (let angle = 0; angle < 360; angle++) {
      for (let r = 0; r < radius; r++) {
        const hue = angle;
        const saturation = (r / radius) * 100;
        const lightness = 50; // Fixed lightness for the wheel

        ctx.fillStyle = `hsl(${hue}, ${saturation}%, ${lightness}%)`;

        const x = centerX + r * Math.cos((angle * Math.PI) / 180);
        const y = centerY + r * Math.sin((angle * Math.PI) / 180);

        ctx.beginPath();
        ctx.arc(x, y, 1.5, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    // Draw hover indicator (larger, semi-transparent)
    if (hoverColor && !showResult) {
      const hoverRadius = (hoverColor.s / 100) * radius;
      const hoverAngle = (hoverColor.h * Math.PI) / 180;
      const hoverX = centerX + hoverRadius * Math.cos(hoverAngle);
      const hoverY = centerY + hoverRadius * Math.sin(hoverAngle);

      ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(hoverX, hoverY, 12, 0, Math.PI * 2);
      ctx.stroke();

      ctx.strokeStyle = 'rgba(0, 0, 0, 0.6)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(hoverX, hoverY, 12, 0, Math.PI * 2);
      ctx.stroke();
    }

    // Draw selection indicator (only if color is selected and result is shown)
    if (colorSelected && showResult) {
      const selectedRadius = (selectedColor.s / 100) * radius;
      const selectedAngle = (selectedColor.h * Math.PI) / 180;
      const selectedX = centerX + selectedRadius * Math.cos(selectedAngle);
      const selectedY = centerY + selectedRadius * Math.sin(selectedAngle);

      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(selectedX, selectedY, 10, 0, Math.PI * 2);
      ctx.stroke();

      ctx.strokeStyle = '#000';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(selectedX, selectedY, 10, 0, Math.PI * 2);
      ctx.stroke();
    }
  }, [selectedColor, hoverColor, colorSelected, showResult]);

  // Handle mouse interaction with color wheel
  const handleWheelInteraction = (e) => {
    const canvas = wheelCanvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = Math.min(centerX, centerY) - 10;

    // Get mouse position relative to canvas
    const mouseX = ((e.clientX - rect.left) * canvas.width) / rect.width;
    const mouseY = ((e.clientY - rect.top) * canvas.height) / rect.height;

    // Calculate distance from center and angle
    const dx = mouseX - centerX;
    const dy = mouseY - centerY;
    const distance = Math.sqrt(dx * dx + dy * dy);

    // Only respond if click is within the wheel
    if (distance <= radius) {
      let angle = Math.atan2(dy, dx) * (180 / Math.PI);
      if (angle < 0) angle += 360; // Convert to 0-360 range

      const saturation = Math.min((distance / radius) * 100, 100);

      setSelectedColor({
        h: Math.round(angle),
        s: Math.round(saturation),
        l: 50 // Fixed lightness
      });

      // Clear any previous result when selecting new color
      setShowResult(false);
      setScore(null);
    }
  };

  // Mouse event handlers for the color wheel
  const handleMouseDown = (e) => {
    isDraggingRef.current = true;
    handleWheelInteraction(e);
  };

  const handleMouseMove = (e) => {
    if (isDraggingRef.current) {
      handleWheelInteraction(e);
    }
  };

  const handleMouseUp = () => {
    isDraggingRef.current = false;
  };

  // Calculate color similarity score (0-100)
  const calculateScore = () => {
    if (!gameStarted) return;

    // Calculate difference in each component
    const hueDiff = Math.min(
      Math.abs(targetColor.h - selectedColor.h),
      360 - Math.abs(targetColor.h - selectedColor.h)
    ); // Handle hue wrap-around
    const satDiff = Math.abs(targetColor.s - selectedColor.s);
    const lightDiff = Math.abs(targetColor.l - selectedColor.l);

    // Weight the differences (hue is most important for color perception)
    const totalDiff = (hueDiff / 180) * 0.6 + (satDiff / 100) * 0.3 + (lightDiff / 100) * 0.1;

    // Convert to score (100 = perfect match, 0 = completely different)
    const calculatedScore = Math.max(0, Math.round((1 - totalDiff) * 100));

    setScore(calculatedScore);
    setShowResult(true);
  };

  // Get score message based on score value
  const getScoreMessage = (score) => {
    if (score >= 95) return "🎯 Perfect! Amazing color vision!";
    if (score >= 85) return "🌟 Excellent! Very close match!";
    if (score >= 70) return "👍 Great job! Good eye for color!";
    if (score >= 50) return "👌 Not bad! Keep practicing!";
    if (score >= 30) return "🤔 Getting warmer... try again!";
    return "💪 Keep trying! You'll get better!";
  };

  // Initialize the color wheel when component mounts
  useEffect(() => {
    drawColorWheel();
  }, [drawColorWheel]);

  // Add global mouse event listeners
  useEffect(() => {
    const handleGlobalMouseMove = (e) => handleMouseMove(e);
    const handleGlobalMouseUp = () => handleMouseUp();

    document.addEventListener('mousemove', handleGlobalMouseMove);
    document.addEventListener('mouseup', handleGlobalMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleGlobalMouseMove);
      document.removeEventListener('mouseup', handleGlobalMouseUp);
    };
  }, []);

  return (
    <div className="color-matching-game">
      {/* Game Header */}
      <div className="game-header">
        <h1 className="game-title">🎨 Color Matching Challenge</h1>
        <p className="game-description">
          Study the target color, then try to match it on the wheel without seeing your selection!
        </p>
      </div>

      {/* Main Game Area */}
      <div className="game-content">
        {/* Left Panel - Target Color and Results */}
        <div className="left-panel">
          <div className="color-display-section">
            <h3>🎯 Target Color</h3>
            <div 
              className="target-color-box"
              style={{ backgroundColor: hslToCss(targetColor) }}
            >
              {!gameStarted && (
                <div className="start-message">
                  Click "New Game" to start!
                </div>
              )}
            </div>

            {gameStarted && showResult && (
              <>
                <h3>🎨 Your Selection</h3>
                <div 
                  className="selected-color-box reveal-animation"
                  style={{ backgroundColor: hslToCss(selectedColor) }}
                />
              </>
            )}
          </div>

          {/* Score Display */}
          {showResult && score !== null && (
            <div className="score-display">
              <div className="score-number">Score: {score}/100</div>
              <div className="score-message">{getScoreMessage(score)}</div>
              <div className="color-values">
                <div className="color-info">
                  <strong>Target:</strong> H:{targetColor.h}° S:{targetColor.s}% L:{targetColor.l}%
                </div>
                <div className="color-info">
                  <strong>Your pick:</strong> H:{selectedColor.h}° S:{selectedColor.s}% L:{selectedColor.l}%
                </div>
              </div>
            </div>
          )}

          {/* Game Controls */}
          <div className="game-controls">
            <button 
              className="new-game-btn"
              onClick={generateNewTarget}
            >
              🎲 New Game
            </button>

            {gameStarted && !showResult && (
              <button 
                className="submit-btn pulse-animation"
                onClick={calculateScore}
              >
                🎯 Reveal My Guess!
              </button>
            )}
          </div>
        </div>

        {/* Right Panel - Color Wheel */}
        <div className="right-panel">
          <div className="color-wheel-section">
            <h3>🎨 Color Wheel</h3>
            <p className="wheel-instructions">
              Click and drag to select a color. You won't see your choice until you submit your guess!
            </p>
            <div className="wheel-container">
              <canvas
                ref={wheelCanvasRef}
                width={500}
                height={500}
                className="color-wheel"
                onMouseMove={handleMouseMove}
                onClick={handleWheelClick}
                style={{ cursor: 'crosshair' }}
              />
            </div>

            {/* Current Selection Info - Only show after result */}
            {showResult && (
              <div className="selection-info">
                <div className="current-selection reveal-animation">
                  <div 
                    className="selection-preview"
                    style={{ backgroundColor: hslToCss(selectedColor) }}
                  />
                  <div className="selection-values">
                    H: {selectedColor.h}° | S: {selectedColor.s}% | L: {selectedColor.l}%
                  </div>
                </div>
              </div>
            )}

            {/* Selection Status - Show while selecting */}
            {gameStarted && !showResult && (
              <div className="selection-status">
                <div className="selection-indicator">
                  <div className="selection-dot"></div>
                  <span>Color selected! Ready to submit your guess.</span>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ColorMatchingGame;
